// 用户点过“采用本周菜单”才算数，所以草稿留在客户端，不落库。
type MealPlan struct {
	CreatedAt time.Time       `json:"created_at"`
	Entries   []MealPlanEntry `json:"entries"`

	// Id Example: mpl_01J8Z3
	Id string `json:"id"`

	// PlannedNutrition **这份菜单本身的能量**，由服务端按菜谱营养求和。
	//
	// 它说的是「照这个方案做出来有多少」，不是用户吃了多少——
	// 用户加不加餐、在外面吃什么，我们不追踪，也不该拿这个数去暗示。
	PlannedNutrition RecipeNutrition `json:"planned_nutrition"`
	UpdatedAt        time.Time       `json:"updated_at"`
	Version          int             `json:"version"`

	// WeekStart 本周第一天。由服务端按用户的 week_start 偏好计算，
	// 客户端不自行推导——周一还是周日开始是用户设置。
	WeekStart openapi_types.Date `json:"week_start"`
}

// MealPlanCandidateCounts defines model for MealPlanCandidateCounts.
type MealPlanCandidateCounts struct {
	Breakfast int `json:"breakfast"`
	Dinner    int `json:"dinner"`
	Lunch     int `json:"lunch"`
}

// MealPlanEntry 菜单里的一道菜。**一格可以有多道**：早餐是主食+蛋白，午晚是主食+荤+素。
//
// 一格一道的话，单道菜的热量中位数只有 318 kcal，
// 按身高体重算出来的每餐目标根本够不到。
type MealPlanEntry struct {
	// Component 这道菜在这一格里扮演什么角色，展示顺序也按它排（主食在前）。
	//
	// 随菜单存下来而不是每次去菜谱里查：菜谱的分类将来可能因规则调整而变，
	// 但用户确认过的那份菜单里“这道是主食”是当时的事实。
	Component *RecipeComponent `json:"component,omitempty"`

	// Date 该餐所在日期。用真实日期而不是“周几”，跨周与跨时区才不会含糊。
	Date     openapi_types.Date `json:"date"`
	MealSlot RecipeMealSlot     `json:"meal_slot"`

	// Recipe 展开的菜谱，列表页据此显示菜名与营养，不用逐条再查。
	Recipe   *Recipe `json:"recipe,omitempty"`
	RecipeId string  `json:"recipe_id"`
}

// MealPlanEntryInput defines model for MealPlanEntryInput.
type MealPlanEntryInput struct {
	// Component 这道菜在这一格里的角色。不传时服务端按菜谱当前的分类填。
	//
	// 提交时带上，是为了让用户确认的那一版原样存下来：
	// 菜谱分类将来可能因规则调整而变，已确认的菜单不该跟着变。
	Component *RecipeComponent   `json:"component,omitempty"`
	Date      openapi_types.Date `json:"date"`
	MealSlot  RecipeMealSlot     `json:"meal_slot"`
	RecipeId  string             `json:"recipe_id"`
}

